import 'package:flutter/material.dart';
import 'package:vector_map/vector_map.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  final geoJson = '{"type":"FeatureCollection","features":[]}'; // your GeoJSON string
  final source = await MapDataSource.geoJson(geoJson: geoJson);
  final layer = MapLayer(dataSource: source);
  final controller = VectorMapController();
  controller.addLayer(layer);
  runApp(MaterialApp(home: Scaffold(body: VectorMap(controller: controller))));
}
